UPDATE tools SET long_description = E'Buddy Punch, c''est pointage en ligne pour le suivi du temps des employés. À partir de 15€/mois. Particulièrement pertinent pour les consultants B2B et les fondateurs SaaS.\n\nCe qui distingue Buddy Punch : spécialisé en time tracking, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 15€/mois.', long_description_en = E'Buddy Punch is online time tracking and attendance software for employees. Starting at €15/month. Most relevant for B2B consultants and SaaS founders.\n\nWhat sets Buddy Punch apart: specialized in time tracking, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €15/month.' WHERE slug = 'buddy-punch';
UPDATE tools SET long_description = E'Hex, c''est notebooks data collaboratifs avec publication en apps interactives. À partir de 20.78€/mois. Particulièrement pertinent pour les data-analyst.\n\nGain de temps estimé : 6h/mois pour un usage régulier.\n\nÀ garder si : analyses data à partager en app interactive avec des stakeholders. À éviter si : metabase ou Looker déjà en place. Pertinent si vous présentez des analyses à des non-techniques.', long_description_en = E'Hex is collaborative data notebooks with interactive app publishing. Starting at €20.78/month. Most relevant for data-analyst.\n\nEstimated time saving: 6h/month with regular use.\n\nKeep it if: data analytics to share in an interactive app with stakeholders. Skip it if: metabase ou Looker déjà en place. Relevant if you present analyses to non-technical stakeholders.' WHERE slug = 'hex';
