UPDATE tools SET long_description = E'Lovable, c''est génération d''applications full-stack depuis un prompt avec Supabase intégré. À partir de 17.32€/mois. Particulièrement pertinent pour les fondateurs SaaS et les ai-builder.\n\nGain de temps estimé : 15h/mois pour un usage régulier.\n\nÀ garder si : construire un SaaS complet sans équipe dev. À éviter si : bolt.new ou Cursor déjà en place — doublon builder. Rentable dès le premier produit qui génère du revenu.', long_description_en = E'Lovable is full-stack app generation from a prompt with integrated Supabase. Starting at €17.32/month. Most relevant for SaaS founders and ai-builder.\n\nEstimated time saving: 15h/month with regular use.' WHERE slug = 'lovable';
UPDATE tools SET long_description = E'Otter.ai, c''est transcription et résumé automatique de réunions en temps réel. À partir de 8.66€/mois. Particulièrement pertinent pour les consultants B2B et les manager-dsi.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : beaucoup de réunions clients à retranscrire. À éviter si : descript déjà en place — doublon transcription. Free tier généreux — rarement nécessaire de payer. Si le budget le permet, descript est souvent une meilleure option.', long_description_en = E'Otter.ai is real-time automatic meeting transcription and summarisation. Starting at €8.66/month. Most relevant for B2B consultants and manager-dsi.\n\nEstimated time saving: 5h/month with regular use.\n\nIf budget allows, descript is often a better fit.' WHERE slug = 'otter-ai';
