UPDATE tools SET long_description = E'Legalstart, c''est création et gestion juridique d''entreprise en ligne. À partir de 15€/mois.\n\nCe qui distingue Legalstart : formulaires guidés pas à pas. Ajoutez à ça documents juridiques conformes, et prix transparent et fixe. Pour les usages intensifs : support juridique par chat. Cas d''usage typique : créer une SASU ou EURL en ligne. On l''utilise aussi pour rédiger des CGV ou contrats de prestation.\n\nÀ garder si : création ou modification de structure juridique ou rédaction de contrats standards. À éviter si : cas juridiques complexes nécessitant un avocat ou grande entreprise avec service juridique. Point de friction : documents standardisés (pas sur-mesure). Rentable dès le premier acte juridique (vs honoraires avocat).', long_description_en = E'Legalstart is online company creation and legal management. Starting at €15/month.' WHERE slug = 'legalstart';
