UPDATE tools SET long_description = E'Leadflow, c''est générateur de leads immobilier alimenté par l’IA. À partir de 20€/mois. Particulièrement pertinent pour les ecommercant et les fondateurs SaaS.\n\nCe qui distingue Leadflow : spécialisé en lead generation, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 20€/mois.', long_description_en = E'Leadflow is aI-powered real estate lead generator. Starting at €20/month. Most relevant for ecommercant and SaaS founders.\n\nWhat sets Leadflow apart: specialized in lead generation, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €20/month.' WHERE slug = 'leadflow';
UPDATE tools SET long_description = E'Payhawk, c''est plateforme tout-en-un dépenses, cartes et factures. À partir de 12€/mois.\n\nCe qui distingue Payhawk : tout-en-un : cartes, frais, factures fournisseurs. Ajoutez à ça workflows d''approbation multi-niveaux, et intégrations ERP natives (NetSuite, Xero, QBO). Pour les usages intensifs : gestion multi-devises. Cas d''usage typique : centraliser toute la gestion des dépenses. On l''utilise aussi pour automatiser les approbations de factures fournisseurs.\n\nÀ garder si : équipe 10+ avec processus financiers complexes ou besoin de consolider cartes + frais + factures. À éviter si : freelance ou micro-équipe ou besoin uniquement de notes de frais. Point de friction : prix premium justifié uniquement pour les PME 10+. Rentable pour les équipes de 10+ personnes avec des flux financiers multiples.', long_description_en = E'Payhawk is all-in-one platform for expenses, cards, and invoices. Starting at €12/month.' WHERE slug = 'payhawk';
UPDATE tools SET long_description = E'Notion AI, c''est iA intégrée dans Notion : rédaction, résumé, traduction directement dans vos docs. À partir de 6.93€/mois. Particulièrement pertinent pour les consultants B2B et les product-manager.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : vous n''avez pas d''abonnement Claude ou ChatGPT. À éviter si : claude ou ChatGPT déjà dans le stack — doublon évident. Inutile si vous avez déjà un abonnement IA généraliste. Si le budget le permet, claude est souvent une meilleure option.', long_description_en = E'Notion AI is aI built into Notion: writing, summarising, translating directly in your docs. Starting at €6.93/month. Most relevant for B2B consultants and product-manager.\n\nEstimated time saving: 3h/month with regular use.\n\nIf budget allows, claude is often a better fit.' WHERE slug = 'notion-ai';
UPDATE tools SET long_description = E'Coast, c''est carte carburant intelligente et gestion des dépenses pour entreprises. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les consultants B2B et les daf-finance.\n\nCe qui distingue Coast : spécialisé en expense management, et interface professionnelle. Gain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Gratuit, à garder si utile.', long_description_en = E'Coast is smart fuel card and expense management for businesses. Core features are free, with paid plans for advanced use. Most relevant for B2B consultants and daf-finance.\n\nWhat sets Coast apart: specialized in expense management, and professional interface. Estimated time saving: 2h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. Free, worth keeping if found useful.' WHERE slug = 'coast';
