UPDATE tools SET long_description = E'Integrately, c''est automatisations en 1 clic entre 1000+ apps. À partir de 20€/mois.\n\nCe qui distingue Integrately : automatisations en 1 clic (pré-configurées). Ajoutez à ça 8 millions+ d''automatisations prêtes, et interface très simple. Pour les usages intensifs : prix compétitif. Cas d''usage typique : connecter deux apps en 1 clic. On l''utilise aussi pour automatiser des tâches répétitives simples.\n\nÀ garder si : besoin d''automatisations simples sans configuration ou non technique. À éviter si : workflows complexes et personnalisés ou besoin de fiabilité enterprise. Point de friction : moins de personnalisation que Zapier/Make. Bon choix pour les automatisations standards sans complexité.', long_description_en = E'Integrately is 1-click automations between 1000+ apps. Starting at €20/month.' WHERE slug = 'integrately';
UPDATE tools SET long_description = E'Whisper (OpenAI), c''est transcription audio open source d''OpenAI. Précis, multilingue, gratuit. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les podcasteur et les créateurs de contenu.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : transcription en volume via pipeline automatisé. À éviter si : descript ou Otter.ai déjà en place pour un usage non-technique. Gratuit — toujours pertinent pour les profils techniques.', long_description_en = E'Whisper (OpenAI) is openAI open-source audio transcription. Accurate, multilingual, free. Core features are free, with paid plans for advanced use. Most relevant for podcasteur and content creators.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'whisper';
UPDATE tools SET long_description = E'Deputy, c''est simplifie la planification et réduit les coûts de main-d’œuvre. À partir de 10€/mois. Particulièrement pertinent pour les manager-dsi et les rh-recruteur.\n\nCe qui distingue Deputy : spécialisé en workforce management, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'Deputy is simplifies scheduling and reduces labor costs. Starting at €10/month. Most relevant for manager-dsi and rh-recruteur.\n\nWhat sets Deputy apart: specialized in workforce management, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: prices to check depending on usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'deputy';
UPDATE tools SET long_description = E'Doppler, c''est gestion centralisée des secrets et variables d''environnement. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Doppler : dashboard centralisé pour tous les secrets. Ajoutez à ça versioning et audit trail, et intégrations CI/CD natives. Pour les usages intensifs : permissions granulaires par environnement. Cas d''usage typique : centraliser les clés API de tous les projets. On l''utilise aussi pour déployer les secrets automatiquement en CI/CD.\n\nÀ garder si : équipe de 2+ développeurs ou secrets partagés entre environnements. À éviter si : développeur solo ou 1-2 projets simples. Point de friction : dépendance à un service cloud tiers. Utile dès 2+ développeurs partageant des secrets sur 2+ environnements.', long_description_en = E'Doppler is centralised secret and environment variable management. Core features are free, with paid plans for advanced use.' WHERE slug = 'doppler';
UPDATE tools SET long_description = E'Adobe Podcast AI, c''est amélioration audio IA : suppression de bruit, égalisation automatique, studio qualité. L''outil est entièrement gratuit. Particulièrement pertinent pour les podcasteur et les créateurs de contenu.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : podcasts ou voix-off avec problèmes de bruit ambiant. À éviter si : descript couvre déjà ce besoin. Gratuit — toujours pertinent si vous avez des problèmes audio.', long_description_en = E'Adobe Podcast AI is aI audio enhancement: noise removal, automatic EQ, studio quality. It''s completely free. Most relevant for podcasteur and content creators.\n\nEstimated time saving: 3h/month with regular use.' WHERE slug = 'adobe-podcast-ai';
