UPDATE tools SET long_description = E'Soldo, c''est cartes prépayées et gestion des frais professionnels. À partir de 6€/mois.\n\nCe qui distingue Soldo : interface simple et intuitive. Ajoutez à ça catégorisation automatique des dépenses, et cartes physiques et virtuelles. Pour les usages intensifs : bon rapport qualité/prix. Cas d''usage typique : distribuer des budgets par département. On l''utilise aussi pour éliminer les avances de frais.\n\nÀ garder si : petite équipe (2-10) avec dépenses régulières ou besoin de simplicité. À éviter si : freelance solo ou besoin de fonctions RH avancées. Point de friction : moins de fonctionnalités que Moss ou Spendesk. Utile dès 5+ transactions mensuelles à suivre.', long_description_en = E'Soldo is prepaid cards and professional expense management. Starting at €6/month.' WHERE slug = 'soldo';
UPDATE tools SET long_description = E'Buzzsprout, c''est l''hébergement podcast le plus simple à prendre en main. Distribution automatique. À partir de 10.39€/mois. Particulièrement pertinent pour les podcasteur.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : podcast avec besoin d''analytics avancés et support réactif. À éviter si : débutant — Spotify for Podcasters (Anchor) est gratuit. Rentable dès 100 écoutes par épisode et 2 épisodes/mois. Alternative gratuite à considérer : anchor-spotify.', long_description_en = E'Buzzsprout is the easiest podcast hosting to get started with. Automatic distribution. Starting at €10.39/month. Most relevant for podcasteur.\n\nEstimated time saving: 3h/month with regular use.\n\nFree alternative worth considering: anchor-spotify.' WHERE slug = 'buzzsprout';
UPDATE tools SET long_description = E'EasyDMARC, c''est saaS pour résoudre les problèmes de sécurité et délivrabilité email. À partir de 10€/mois. Particulièrement pertinent pour les manager-dsi et les developpeur-solo.\n\nCe qui distingue EasyDMARC : spécialisé en email security, et interface professionnelle. Gain de temps estimé : 8h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'EasyDMARC is saaS to solve email security and deliverability issues. Starting at €10/month. Most relevant for manager-dsi and solo developers.\n\nWhat sets EasyDMARC apart: specialized in email security, and professional interface. Estimated time saving: 8h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to be verified based on usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'easydmarc';
UPDATE tools SET long_description = E'Kelio, c''est gestion des temps et planification RH. À partir de 8€/mois.\n\nCe qui distingue Kelio : pointeuse intégrée (physique ou mobile). Ajoutez à ça planification des équipes intuitive, et gestion des absences et congés. Pour les usages intensifs : adapté au travail posté et horaires variables. Cas d''usage typique : suivre les heures travaillées automatiquement. On l''utilise aussi pour planifier les rotations d''équipe.\n\nÀ garder si : équipe avec horaires variables ou besoin de pointeuse. À éviter si : équipe 100% remote ou freelance. Point de friction : interface fonctionnelle mais peu moderne. Utile dès 5+ personnes avec des horaires à gérer.', long_description_en = E'Kelio is time management and HR scheduling. Starting at €8/month.' WHERE slug = 'kelio';
UPDATE tools SET long_description = E'Audacity, c''est logiciel de montage audio open source. Gratuit, puissant, universel. L''outil est entièrement gratuit. Particulièrement pertinent pour les podcasteur et les créateurs de contenu.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : montage audio basique, pas besoin de transcription. À éviter si : volume important — Descript est bien plus rapide. Gratuit — toujours pertinent pour les petits volumes. Si le budget le permet, descript est souvent une meilleure option.', long_description_en = E'Audacity is open-source audio editing software. Free, powerful, universal. It''s completely free. Most relevant for podcasteur and content creators.\n\nEstimated time saving: 4h/month with regular use.\n\nIf budget allows, descript is often a better fit.' WHERE slug = 'audacity';
UPDATE tools SET long_description = E'Finale Inventory, c''est solution de gestion des stocks pour vendeurs à gros volume. À partir de 10€/mois. Particulièrement pertinent pour les fondateurs SaaS et les developpeur-solo.\n\nCe qui distingue Finale Inventory : spécialisé en inventory management, et interface professionnelle. Gain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'Finale Inventory is inventory management solution for high-volume sellers. Starting at €10/month. Most relevant for SaaS founders and solo developers.\n\nWhat sets Finale Inventory apart: specialized in inventory management, and professional interface. Estimated time saving: 5h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to be verified based on usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'finale-inventory';
UPDATE tools SET long_description = E'Captaindoc, c''est automatisation de documents juridiques et contractuels. À partir de 19€/mois.\n\nCe qui distingue Captaindoc : modèles de documents personnalisables. Ajoutez à ça génération automatisée et rapide, et archivage et suivi des versions. Pour les usages intensifs : interface intuitive. Cas d''usage typique : générer des contrats de prestation personnalisés. On l''utilise aussi pour automatiser les avenants.\n\nÀ garder si : production régulière de contrats similaires ou besoin d''automatiser la documentation. À éviter si : cas juridiques sur-mesure ou volume faible de documents. Point de friction : catalogue de modèles à enrichir. Utile dès 5+ documents contractuels par mois.', long_description_en = E'Captaindoc is legal and contractual document automation. Starting at €19/month.' WHERE slug = 'captaindoc';
UPDATE tools SET long_description = E'Podia, c''est vente de cours, webinaires et téléchargements numériques. 0% commission. À partir de 28.58€/mois. Particulièrement pertinent pour les coach-formateur et les créateurs de contenu.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : vente de produits numériques simples sans communauté. À éviter si : kajabi déjà en place — doublon LMS. Rentable dès 5 ventes de cours par mois. Si le budget le permet, kajabi est souvent une meilleure option.', long_description_en = E'Podia is sell courses, webinars, and digital downloads. 0% commission. Starting at €28.58/month. Most relevant for coach-formateur and content creators.\n\nEstimated time saving: 4h/month with regular use.\n\nIf budget allows, kajabi is often a better fit.' WHERE slug = 'podia';
UPDATE tools SET long_description = E'Format, c''est constructeur de portfolio en ligne pour professionnels créatifs. À partir de 20€/mois. Particulièrement pertinent pour les graphiste-da et les community-manager.\n\nCe qui distingue Format : spécialisé en portfolio builder, et interface professionnelle. Gain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 20€/mois.', long_description_en = E'Format is online portfolio builder for creative professionals. Starting at €20/month. Most relevant for graphiste-da and community-manager.\n\nWhat sets Format apart: specialized portfolio builder, and professional interface. Estimated time saving: 5h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €20/month.' WHERE slug = 'format';
UPDATE tools SET long_description = E'Rydoo, c''est notes de frais automatisées avec OCR. À partir de 8€/mois.\n\nCe qui distingue Rydoo : oCR puissant avec extraction automatique des montants. Ajoutez à ça conformité TVA multi-pays européenne, et application mobile excellente. Pour les usages intensifs : intégration SAP, Oracle, NetSuite. Cas d''usage typique : scanner les reçus restaurant et transport en déplacement. On l''utilise aussi pour gérer les per diem automatiquement.\n\nÀ garder si : déplacements professionnels fréquents ou facturation multi-pays. À éviter si : travail 100% remote sans déplacements ou moins de 3 notes de frais par mois. Point de friction : prix par utilisateur qui monte vite. Rentable dès 2+ déplacements professionnels par mois.', long_description_en = E'Rydoo is automated expense reports with OCR. Starting at €8/month.' WHERE slug = 'rydoo';

